css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .pin { position: absolute; top: 8%; left: 47%; width: 6%; height: 56%; border-radius: 3px; background: linear-gradient(#f1f5f9, #94a3b8); transform-origin: 50% 92%; }
.loader .pin::after { content: ''; position: absolute; left: -20%; top: -6%; width: 140%; height: 9%; border-radius: 50%; background: var(--accent); }
.loader .pin:nth-of-type(1) { animation: knit-left calc(var(--loader-speed) * 1.4) ease-in-out infinite; }
.loader .pin:nth-of-type(2) { animation: knit-right calc(var(--loader-speed) * 1.4) ease-in-out infinite; }
.loader .ball { position: absolute; bottom: 3%; left: 31%; width: 38%; height: 38%; border-radius: 50%; background: repeating-conic-gradient(from 0deg, var(--accent) 0 12%, var(--accent-2) 0 24%); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 18%, transparent); animation: knit-roll calc(var(--loader-speed) * 3) linear infinite; }
@keyframes knit-left { 0%, 100% { transform: rotate(-28deg); } 50% { transform: rotate(-7deg); } }
@keyframes knit-right { 0%, 100% { transform: rotate(28deg); } 50% { transform: rotate(7deg); } }
@keyframes knit-roll { to { transform: rotate(-1turn); } }
